const { useState } = React;

function Quantity() {
  const [quantity, setQuantity] = useState(0);

  function increase() { setQuantity((value) => value + 1); }
  function decrease() { setQuantity((value) => Math.max(0, value - 1)); }
  function reset() { setQuantity(0); }

  return (
    <section>
      <p>수량: {quantity}</p>
      <button type="button" onClick={increase}>증가</button>
      <button type="button" onClick={decrease}>감소</button>
      <button type="button" onClick={reset}>초기화</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Quantity />);

